<?php
/** Schema7: private attachments, payroll snapshots and fixed-asset ledger. Additive only. */
namespace Agah\Erp\Core;
if(!defined('ABSPATH'))exit;
final class OperationsSchema {
    public static function tables(){return ['files','employees','contracts','attendance','payroll_params','payslips','payslip_items','assets','asset_events']; }
    public static function ddl($p,$c){$defs=[
'files'=>"invoice_id bigint(20) unsigned DEFAULT NULL,\n  voucher_id bigint(20) unsigned DEFAULT NULL,\n  party_id bigint(20) unsigned DEFAULT NULL,\n  expense_id bigint(20) unsigned DEFAULT NULL,\n  employee_id bigint(20) unsigned DEFAULT NULL,\n  original_name varchar(190) NOT NULL,\n  stored_name char(64) NOT NULL,\n  category varchar(80) NOT NULL DEFAULT '',\n  mime varchar(60) NOT NULL,\n  sha256 char(64) NOT NULL,\n  byte_size int(10) unsigned NOT NULL,\n  file_data mediumblob NOT NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  KEY company_search (company_id,category),",
'employees'=>"code varchar(30) NOT NULL,\n  name varchar(190) NOT NULL,\n  detail_id bigint(20) unsigned NOT NULL,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  national_id_enc varchar(400) NOT NULL DEFAULT '',\n  national_id_idx char(64) NOT NULL DEFAULT '',\n  personnel_no varchar(30) NOT NULL DEFAULT '',\n  phone varchar(40) NOT NULL DEFAULT '',\n  email varchar(190) NOT NULL DEFAULT '',\n  education varchar(100) NOT NULL DEFAULT '',\n  address varchar(500) NOT NULL DEFAULT '',\n  dependents tinyint(3) unsigned NOT NULL DEFAULT 0,\n  employment_status varchar(12) NOT NULL DEFAULT 'active',\n  iban varchar(26) NOT NULL DEFAULT '',\n  insurance_no varchar(20) NOT NULL DEFAULT '',\n  hire_date date DEFAULT NULL,\n  leave_date date DEFAULT NULL,\n  UNIQUE KEY company_code (company_id,code),\n  KEY company_national (company_id,national_id_idx),",
'contracts'=>"employee_id bigint(20) unsigned NOT NULL,\n  start_date date NOT NULL,\n  end_date date NOT NULL,\n  base_salary bigint(20) unsigned NOT NULL,\n  benefits bigint(20) unsigned NOT NULL,\n  benefits_insurance_exempt bigint(20) unsigned NOT NULL DEFAULT 0,\n  benefits_tax_exempt bigint(20) unsigned NOT NULL DEFAULT 0,\n  overtime_base_extra bigint(20) unsigned NOT NULL DEFAULT 0,\n  contract_type varchar(10) NOT NULL DEFAULT 'full',\n  hourly_rate bigint(20) unsigned NOT NULL DEFAULT 0,\n  project_amount bigint(20) unsigned NOT NULL DEFAULT 0,\n  weekly_minutes int(10) unsigned NOT NULL DEFAULT 0,\n  version int(10) unsigned NOT NULL DEFAULT 1,\n  parent_id bigint(20) unsigned DEFAULT NULL,\n  items_json text NULL,\n  KEY company_employee (company_id,employee_id,start_date,end_date),",
'attendance'=>"employee_id bigint(20) unsigned NOT NULL,\n  fiscal_year_id bigint(20) unsigned NOT NULL,\n  period_key char(7) NOT NULL,\n  work_days int(10) unsigned NOT NULL,\n  leave_days int(10) unsigned NOT NULL,\n  overtime_minutes int(10) unsigned NOT NULL,\n  extra_benefits bigint(20) unsigned NOT NULL,\n  extra_insurance_exempt bigint(20) unsigned NOT NULL DEFAULT 0,\n  extra_tax_exempt bigint(20) unsigned NOT NULL DEFAULT 0,\n  deductions bigint(20) unsigned NOT NULL,\n  work_minutes int(10) unsigned NOT NULL DEFAULT 0,\n  mission_days int(10) unsigned NOT NULL DEFAULT 0,\n  absence_days int(10) unsigned NOT NULL DEFAULT 0,\n  project_permille int(10) unsigned NOT NULL DEFAULT 0,\n  UNIQUE KEY company_period (company_id,employee_id,period_key),",
